void nexa_snapshot_test_set_failpoint(int failpoint){snapshotRestoreFailpoint=failpoint;}
#endif

int nexa_snapshot_save_bundle(NexaContext*c,uint64_t id,const char*vmPath,const char*diskDirectory){return guard(c,[&]{if(!vmPath||!*vmPath||!diskDirectory||!*diskDirectory)throw std::invalid_argument("Snapshot paths must not be empty");auto key=session(c,id);auto&vm=c->sessions.machine(key);auto pi=c->diskPaths.find(id);if(pi!=c->diskPaths.end())for(const auto&[device,path]:pi->second)c->disks.at(id).at(device)->flush();const auto dir=std::filesystem::path(diskDirectory);std::filesystem::create_directories(dir);const auto vmFile=std::filesystem::path(vmPath);const auto tempVm=std::filesystem::path(std::string(vmPath)+".tmp");vm.saveState(tempVm.string());std::map<uint32_t,std::filesystem::path> diskFiles;if(pi!=c->diskPaths.end())for(const auto&[device,path]:pi->second){auto target=dir/(std::string("device-")+std::to_string(device)+".disk");auto temp=std::filesystem::path(target.string()+".tmp");std::filesystem::copy_file(path,temp,std::filesystem::copy_options::overwrite_existing);diskFiles.emplace(device,temp);}std::ofstream manifest(dir/"manifest.txt.tmp",std::ios::trunc);if(!manifest)throw std::runtime_error("Cannot create snapshot manifest");manifest<<"NEXA_BUNDLE 1\nVM "<<std::filesystem::file_size(tempVm)<<" "<<checksumFile(tempVm)<<"\n";for(const auto&[device,temp]:diskFiles)manifest<<"DISK "<<device<<" "<<std::filesystem::file_size(temp)<<" "<<checksumFile(temp)<<"\n";manifest.close();if(!manifest)throw std::runtime_error("Failed writing snapshot manifest");std::filesystem::copy_file(tempVm,vmFile,std::filesystem::copy_options::overwrite_existing);std::filesystem::remove(tempVm);for(const auto&[device,temp]:diskFiles){auto target=dir/(std::string("device-")+std::to_string(device)+".disk");std::filesystem::copy_file(temp,target,std::filesystem::copy_options::overwrite_existing);std::filesystem::remove(temp);}std::filesystem::copy_file(dir/"manifest.txt.tmp",dir/"manifest.txt",std::filesystem::copy_options::overwrite_existing);std::filesystem::remove(dir/"manifest.txt.tmp");});}
int nexa_snapshot_recover_bundle(NexaContext*c,uint64_t id,const char*vmPath,const char*diskDirectory){return guard(c,[&]{if(!vmPath||!*vmPath||!diskDirectory||!*diskDirectory)throw std::invalid_argument("Recovery paths must not be empty");auto key=session(c,id);auto&vm=c->sessions.machine(key);const auto rollbackDir=std::filesystem::path(std::string(diskDirectory)+".rollback");const auto coordinator=rollbackDir/"transaction.journal";const auto committedMarker=std::filesystem::path(std::string(diskDirectory)+".nexa-committed");if(std::filesystem::exists(committedMarker)){std::ifstream marker(committedMarker);std::string magic;unsigned version=0;marker>>magic>>version;if(!marker||magic!="NEXA_BUNDLE_COMMITTED"||version!=1)throw std::runtime_error("Invalid VM snapshot commit marker");if(std::filesystem::exists(coordinator))nexa::snapshot::recoverCoordinator(coordinator);vm.loadState(vmPath);std::filesystem::remove_all(rollbackDir);std::filesystem::remove(committedMarker);nexa::snapshot::syncDirectory(committedMarker.parent_path());return;}if(std::filesystem::exists(coordinator)){nexa::snapshot::JournalPhase phase{};nexa::snapshot::readJournal(coordinator,phase);nexa::snapshot::recoverCoordinator(coordinator);if(phase==nexa::snapshot::JournalPhase::Prepared){const auto rollbackVm=rollbackDir/"current.vm";if(!std::filesystem::exists(rollbackVm))throw std::runtime_error("Interrupted snapshot transaction is missing its VM rollback image");vm.loadState(rollbackVm.string());}else{vm.loadState(vmPath);}}else{auto pi=c->diskPaths.find(id);if(pi!=c->diskPaths.end())for(const auto&[device,path]:pi->second){(void)device;nexa::snapshot::recover(std::filesystem::path(path+".nexa-journal"));}}auto di=c->disks.find(id);if(di!=c->disks.end())for(const auto&[device,disk]:di->second){(void)device;disk->load();}if(std::filesystem::exists(rollbackDir))std::filesystem::remove_all(rollbackDir);});}
